#[derive(Debug)]
struct DirHandle {", "newString": "pub const FUSE_ROOT_INODE: InodeNo = 1u64;

/// A bounded cache remembering recent lookups that failed because the object did not exist in S3.
///
/// Serving these "negative" lookups from memory avoids repeatedly issuing HEAD and LIST requests for
/// files that are known to be missing. Entries expire after a TTL and are also invalidated when a
/// `readdir`/`readdirplus` later discovers the previously-missing file.
#[cfg(feature = "negative_cache")]
#[derive(Debug)]
struct NegativeCache {
    max_size: usize,
    ttl: Duration,
    entries: crate::sync::Mutex<linked_hash_map::LinkedHashMap<(InodeNo, OsString), std::time::Instant>>,
}

#[cfg(feature = "negative_cache")]
impl NegativeCache {
    fn new(max_size: usize, ttl: Duration) -> Self {
        Self {
            max_size,
            ttl,
            entries: crate::sync::Mutex::new(linked_hash_map::LinkedHashMap::new()),
        }
    }

    /// Returns `true` if a non-expired negative entry exists for `(parent, name)`.
    fn contains(&self, parent: InodeNo, name: &OsStr) -> bool {
        let key = (parent, name.to_owned());
        let mut entries = self.entries.lock().unwrap();
        // `get_refresh` marks the entry as most-recently-used.
        match entries.get_refresh(&key) {
            Some(expiry) => {
                if *expiry >= std::time::Instant::now() {
                    true
                } else {
                    entries.remove(&key);
                    false
                }
            }
            None => false,
        }
    }

    /// Remembers that `(parent, name)` was not found, evicting the least-recently-used entry if the
    /// cache is full.
    fn insert(&self, parent: InodeNo, name: &OsStr) {
        if self.max_size == 0 {
            return;
        }
        let key = (parent, name.to_owned());
        let mut entries = self.entries.lock().unwrap();
        entries.insert(key, std::time::Instant::now() + self.ttl);
        while entries.len() > self.max_size {
            entries.pop_front();
        }
    }

    /// Removes any negative entry for `(parent, name)`, e.g. once the file is known to exist.
    fn remove(&self, parent: InodeNo, name: &OsStr) {
        let key = (parent, name.to_owned());
        self.entries.lock().unwrap().remove(&key);
    }
}

