/// that can be represented as an `Instant` expiry without risking overflow.
const TTL_MAX_SECONDS: u64 = 3_153_600_000;

fn parse_ttl_seconds(seconds_str: &str) -> anyhow::Result<Duration> {
    // Parsing as a `u64` yields the standard "number too large to fit in target type" message on
    // overflow, which we surface verbatim.
    let seconds: u64 = seconds_str.parse()?;
    if seconds > TTL_MAX_SECONDS {
        return Err(anyhow!(
            "TTL must not be greater than {TTL_MAX_SECONDS}s (~100 years)"
        ));
